user_prompt:
method fruit_distribution(s: string, n: int) returns (mangoCount: int)
    requires n >= 0
    requires s != ""
    ensures mangoCount == n - count_apples(s) - count_oranges(s)
{
    // The implementation would go here, assuming helper methods count_apples and count_oranges
    // are defined to extract the number of apples and oranges from the string s.
}

problem_data.canonical_solution:
lis = list()
for i in s.split(' '):
    if i.isdigit():
        lis.append(int(i))
return n - sum(lis)
